package br.com.admeclesial.infrastructure.persistence.relatorio;
import br.com.admeclesial.domain.organizacao.OrganizacaoEclesial;
import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param;
import java.math.BigDecimal; import java.time.LocalDate; import java.util.UUID;
public interface DashboardRepository extends JpaRepository<OrganizacaoEclesial,Long>{
 interface Operacional { Long getPessoasAtivas(); Long getTurmasAtivas(); Long getInscritosAtivos(); Long getProjetosExecucao(); Long getSacramentosPeriodo(); Long getTurmasSemCatequistaPrincipal(); }
 interface Consulta { Long getPessoasAtivas(); Long getTurmasAtivas(); Long getInscritosAtivos(); Long getSacramentosPeriodo(); Long getProjetosExecucao(); }
 interface Secretaria { Long getPessoasAtivas(); Long getNovosCadastros(); Long getSacramentosRegistrados(); Long getMatrimoniosRegistrados(); Long getTurmasAtivas(); Long getTurmasSemCatequistaPrincipal(); }
 interface Catequese { Long getTurmasAtivas(); Long getInscritosAtivos(); Long getVagasDisponiveis(); Long getTurmasSemCatequistaPrincipal(); Long getTurmasSemVagas(); }
 interface Financeiro { BigDecimal getEntradas(); BigDecimal getSaidas(); Long getContribuicoes(); BigDecimal getValorContribuicoes(); Long getContasVencidas(); BigDecimal getSaldoContasVencidas(); Long getRepassesVencidos(); BigDecimal getSaldoRepassesVencidos(); Long getProjetosExecucao(); BigDecimal getRecursosVinculados(); BigDecimal getRecursosUtilizados(); Long getProjetosRecursoSemUso(); }
 @Query(value="""
 select
 (select count(distinct p.id) from adm_eclesial.pessoa p join adm_eclesial.vinculo_pessoa_organizacao_eclesial v on v.pessoa_id=p.id join adm_eclesial.organizacao_eclesial o on o.id=v.organizacao_eclesial_id where o.uuid=:org and p.ativo=true and v.status='ATIVO' and (v.data_fim is null or v.data_fim>=current_date)) pessoasAtivas,
 (select count(*) from adm_eclesial.turma_catequese t join adm_eclesial.organizacao_eclesial o on o.id=t.organizacao_eclesial_id where o.uuid=:org and t.status='ATIVA') turmasAtivas,
 (select count(*) from adm_eclesial.inscricao_catequese i join adm_eclesial.turma_catequese t on t.id=i.turma_catequese_id join adm_eclesial.organizacao_eclesial o on o.id=t.organizacao_eclesial_id where o.uuid=:org and i.status='ATIVA') inscritosAtivos,
 (select count(*) from adm_eclesial.projeto p join adm_eclesial.organizacao_eclesial o on o.id=p.organizacao_eclesial_id where o.uuid=:org and p.status='EM_EXECUCAO') projetosExecucao,
 (select count(*) from adm_eclesial.sacramento s join adm_eclesial.organizacao_eclesial o on o.id=s.organizacao_eclesial_id where o.uuid=:org and s.data_celebracao between :inicio and :fim) sacramentosPeriodo,
 (select count(*) from adm_eclesial.turma_catequese t join adm_eclesial.organizacao_eclesial o on o.id=t.organizacao_eclesial_id where o.uuid=:org and t.status='ATIVA' and not exists(select 1 from adm_eclesial.catequista_turma ct where ct.turma_catequese_id=t.id and ct.principal=true and ct.data_inicio<=current_date and (ct.data_fim is null or ct.data_fim>=current_date))) turmasSemCatequistaPrincipal
 """,nativeQuery=true) Operacional operacional(@Param("org") UUID org,@Param("inicio") LocalDate inicio,@Param("fim") LocalDate fim);
 @Query(value="""
 select
 (select count(distinct p.id) from adm_eclesial.pessoa p join adm_eclesial.vinculo_pessoa_organizacao_eclesial v on v.pessoa_id=p.id join adm_eclesial.organizacao_eclesial o on o.id=v.organizacao_eclesial_id where o.uuid=:org and p.ativo=true and v.status='ATIVO' and (v.data_fim is null or v.data_fim>=current_date)) pessoasAtivas,
 (select count(*) from adm_eclesial.turma_catequese t join adm_eclesial.organizacao_eclesial o on o.id=t.organizacao_eclesial_id where o.uuid=:org and t.status='ATIVA') turmasAtivas,
 (select count(*) from adm_eclesial.inscricao_catequese i join adm_eclesial.turma_catequese t on t.id=i.turma_catequese_id join adm_eclesial.organizacao_eclesial o on o.id=t.organizacao_eclesial_id where o.uuid=:org and t.status='ATIVA' and i.status='ATIVA') inscritosAtivos,
 (select count(*) from adm_eclesial.sacramento s join adm_eclesial.organizacao_eclesial o on o.id=s.organizacao_eclesial_id where o.uuid=:org and s.status<>'CANCELADO' and s.data_registro::date between :inicio and :fim) sacramentosPeriodo,
 (select count(*) from adm_eclesial.projeto p join adm_eclesial.organizacao_eclesial o on o.id=p.organizacao_eclesial_id where o.uuid=:org and p.status='EM_EXECUCAO') projetosExecucao
 """,nativeQuery=true) Consulta consulta(@Param("org") UUID org,@Param("inicio") LocalDate inicio,@Param("fim") LocalDate fim);
 @Query(value="""
 select
 (select count(distinct p.id) from adm_eclesial.pessoa p join adm_eclesial.vinculo_pessoa_organizacao_eclesial v on v.pessoa_id=p.id join adm_eclesial.organizacao_eclesial o on o.id=v.organizacao_eclesial_id where o.uuid=:org and p.ativo=true and v.status='ATIVO' and (v.data_fim is null or v.data_fim>=current_date)) pessoasAtivas,
 (select count(distinct p.id) from adm_eclesial.pessoa p join adm_eclesial.vinculo_pessoa_organizacao_eclesial v on v.pessoa_id=p.id join adm_eclesial.organizacao_eclesial o on o.id=v.organizacao_eclesial_id where o.uuid=:org and p.data_cadastro::date between :inicio and :fim) novosCadastros,
 (select count(*) from adm_eclesial.sacramento s join adm_eclesial.organizacao_eclesial o on o.id=s.organizacao_eclesial_id where o.uuid=:org and s.status<>'CANCELADO' and s.data_registro::date between :inicio and :fim) sacramentosRegistrados,
 (select count(*) from adm_eclesial.matrimonio m join adm_eclesial.processo_matrimonial pm on pm.id=m.processo_matrimonial_id join adm_eclesial.organizacao_eclesial o on o.id=pm.organizacao_eclesial_id where o.uuid=:org and m.data_registro between :inicio and :fim) matrimoniosRegistrados,
 (select count(*) from adm_eclesial.turma_catequese t join adm_eclesial.organizacao_eclesial o on o.id=t.organizacao_eclesial_id where o.uuid=:org and t.status='ATIVA') turmasAtivas,
 (select count(*) from adm_eclesial.turma_catequese t join adm_eclesial.organizacao_eclesial o on o.id=t.organizacao_eclesial_id where o.uuid=:org and t.status='ATIVA' and not exists(select 1 from adm_eclesial.catequista_turma ct where ct.turma_catequese_id=t.id and ct.principal=true and ct.data_inicio<=current_date and (ct.data_fim is null or ct.data_fim>=current_date))) turmasSemCatequistaPrincipal
 """,nativeQuery=true) Secretaria secretaria(@Param("org") UUID org,@Param("inicio") LocalDate inicio,@Param("fim") LocalDate fim);
 @Query(value="""
 select
 (select count(*) from adm_eclesial.turma_catequese t join adm_eclesial.organizacao_eclesial o on o.id=t.organizacao_eclesial_id where o.uuid=:org and t.status='ATIVA') turmasAtivas,
 (select count(*) from adm_eclesial.inscricao_catequese i join adm_eclesial.turma_catequese t on t.id=i.turma_catequese_id join adm_eclesial.organizacao_eclesial o on o.id=t.organizacao_eclesial_id where o.uuid=:org and t.status='ATIVA' and i.status='ATIVA') inscritosAtivos,
 (select coalesce(sum(greatest(coalesce(t.capacidade,0)-(select count(*) from adm_eclesial.inscricao_catequese i where i.turma_catequese_id=t.id and i.status='ATIVA'),0)),0) from adm_eclesial.turma_catequese t join adm_eclesial.organizacao_eclesial o on o.id=t.organizacao_eclesial_id where o.uuid=:org and t.status='ATIVA') vagasDisponiveis,
 (select count(*) from adm_eclesial.turma_catequese t join adm_eclesial.organizacao_eclesial o on o.id=t.organizacao_eclesial_id where o.uuid=:org and t.status='ATIVA' and not exists(select 1 from adm_eclesial.catequista_turma ct where ct.turma_catequese_id=t.id and ct.principal=true and ct.data_inicio<=current_date and (ct.data_fim is null or ct.data_fim>=current_date))) turmasSemCatequistaPrincipal,
 (select count(*) from adm_eclesial.turma_catequese t join adm_eclesial.organizacao_eclesial o on o.id=t.organizacao_eclesial_id where o.uuid=:org and t.status='ATIVA' and t.capacidade is not null and (select count(*) from adm_eclesial.inscricao_catequese i where i.turma_catequese_id=t.id and i.status='ATIVA')>=t.capacidade) turmasSemVagas
 """,nativeQuery=true) Catequese catequese(@Param("org") UUID org);
 @Query(value="""
 with pago_parcela as (select pa.id parcela_id,coalesce(sum(a.valor),0) pago from adm_eclesial.parcela_a_pagar pa left join adm_eclesial.alocacao_pagamento a on a.parcela_a_pagar_id=pa.id group by pa.id),
 contas_vencidas as (select cp.id,greatest(cp.valor_total-coalesce(sum(pp.pago),0),0) saldo from adm_eclesial.conta_a_pagar cp join adm_eclesial.organizacao_eclesial o on o.id=cp.organizacao_eclesial_id left join adm_eclesial.parcela_a_pagar pa on pa.conta_a_pagar_id=cp.id left join pago_parcela pp on pp.parcela_id=pa.id where o.uuid=:org and cp.status<>'CANCELADA' group by cp.id having bool_or(pa.status<>'CANCELADA' and pa.vencimento<current_date and pa.valor-coalesce(pp.pago,0)>0)),
 pago_repasse as (select cp.obrigacao_repasse_id,coalesce(sum(a.valor),0) pago from adm_eclesial.conta_a_pagar cp left join adm_eclesial.parcela_a_pagar pa on pa.conta_a_pagar_id=cp.id left join adm_eclesial.alocacao_pagamento a on a.parcela_a_pagar_id=pa.id where cp.obrigacao_repasse_id is not null and cp.status<>'CANCELADA' group by cp.obrigacao_repasse_id)
 select
 coalesce((select sum(case when m.tipo='ENTRADA' and m.status='CONFIRMADA' then m.valor else 0 end) from adm_eclesial.movimentacao_financeira m join adm_eclesial.conta_financeira c on c.id=m.conta_financeira_id join adm_eclesial.organizacao_eclesial o on o.id=c.organizacao_eclesial_id where o.uuid=:org and m.data_movimentacao between :inicio and :fim),0) entradas,
 coalesce((select sum(case when m.tipo='SAIDA' and m.status='CONFIRMADA' then m.valor else 0 end) from adm_eclesial.movimentacao_financeira m join adm_eclesial.conta_financeira c on c.id=m.conta_financeira_id join adm_eclesial.organizacao_eclesial o on o.id=c.organizacao_eclesial_id where o.uuid=:org and m.data_movimentacao between :inicio and :fim),0) saidas,
 (select count(*) from adm_eclesial.contribuicao c join adm_eclesial.organizacao_eclesial o on o.id=c.organizacao_eclesial_id where o.uuid=:org and c.data_contribuicao between :inicio and :fim) contribuicoes,
 coalesce((select sum(c.valor) from adm_eclesial.contribuicao c join adm_eclesial.organizacao_eclesial o on o.id=c.organizacao_eclesial_id where o.uuid=:org and c.data_contribuicao between :inicio and :fim),0) valorContribuicoes,
 (select count(*) from contas_vencidas) contasVencidas,coalesce((select sum(saldo) from contas_vencidas),0) saldoContasVencidas,
 (select count(*) from adm_eclesial.obrigacao_repasse ob join adm_eclesial.regra_repasse r on r.id=ob.regra_repasse_id join adm_eclesial.organizacao_eclesial o on o.id=r.organizacao_origem_id left join pago_repasse pr on pr.obrigacao_repasse_id=ob.id where o.uuid=:org and ob.status<>'CANCELADA' and ob.data_vencimento<current_date and ob.valor_repasse-coalesce(pr.pago,0)>0) repassesVencidos,
 coalesce((select sum(greatest(ob.valor_repasse-coalesce(pr.pago,0),0)) from adm_eclesial.obrigacao_repasse ob join adm_eclesial.regra_repasse r on r.id=ob.regra_repasse_id join adm_eclesial.organizacao_eclesial o on o.id=r.organizacao_origem_id left join pago_repasse pr on pr.obrigacao_repasse_id=ob.id where o.uuid=:org and ob.status<>'CANCELADA' and ob.data_vencimento<current_date and ob.valor_repasse-coalesce(pr.pago,0)>0),0) saldoRepassesVencidos,
 (select count(*) from adm_eclesial.projeto p join adm_eclesial.organizacao_eclesial o on o.id=p.organizacao_eclesial_id where o.uuid=:org and p.status='EM_EXECUCAO') projetosExecucao,
 coalesce((select sum(f.valor_alocado) from adm_eclesial.fonte_recurso_projeto f join adm_eclesial.projeto p on p.id=f.projeto_id join adm_eclesial.organizacao_eclesial o on o.id=p.organizacao_eclesial_id where o.uuid=:org),0) recursosVinculados,
 coalesce((select sum(u.valor) from adm_eclesial.utilizacao_recurso u join adm_eclesial.fonte_recurso_projeto f on f.id=u.fonte_recurso_projeto_id join adm_eclesial.projeto p on p.id=f.projeto_id join adm_eclesial.organizacao_eclesial o on o.id=p.organizacao_eclesial_id where o.uuid=:org),0) recursosUtilizados,
 (select count(*) from adm_eclesial.projeto p join adm_eclesial.organizacao_eclesial o on o.id=p.organizacao_eclesial_id where o.uuid=:org and (select coalesce(sum(f.valor_alocado),0) from adm_eclesial.fonte_recurso_projeto f where f.projeto_id=p.id)>0 and (select coalesce(sum(u.valor),0) from adm_eclesial.utilizacao_recurso u where u.fonte_recurso_projeto_id in(select f2.id from adm_eclesial.fonte_recurso_projeto f2 where f2.projeto_id=p.id))=0) projetosRecursoSemUso
 """,nativeQuery=true) Financeiro financeiro(@Param("org") UUID org,@Param("inicio") LocalDate inicio,@Param("fim") LocalDate fim);
}
